{
  "verdict": "FAIL",
  "issues": [
    {
      "issueType": "evidence_strength_mismatch",
      "severity": "HIGH",
      "reason": "候选声称evidenceStrength为STRONG_INFERENCE，但所有支撑claim均为人物说法（unverified），且mustNotBeTreatedAsObjectiveFact为true。从人物说法无法强推断出巡抚会主动争夺速度、复核权和解释权这一机制。"
    },
    {
      "issueType": "precondition_not_supported",
      "severity": "HIGH",
      "reason": "precondition '巡抚已经通过合法或半公开渠道得知该行动' 无任何claim支持。原著中巡抚得知信息的渠道未在提供的claim中体现，属于未支持的假设。"
    },
    {
      "issueType": "allowed_move_not_supported",
      "severity": "MEDIUM",
      "reason": "allowedMoves如'派幕僚参加复核'、'提出边办边查'、'抢先形成地方奏报'在提供的claim中无直接或间接证据。claim仅涉及报告呈递方式、胡宗宪意图、郑泌昌和杨金水的表态，未涉及巡抚的具体行动。"
    },
    {
      "issueType": "invariant_not_supported",
      "severity": "MEDIUM",
      "reason": "invariant '巡抚必须有自己的目标和行动能力' 无claim支持。提供的claim中巡抚角色未出现，无法推断其目标和能力。"
    },
    {
      "issueType": "limitation_contradicts_evidence",
      "severity": "LOW",
      "reason": "limitation称'由原著地方官僚自保机制强推断'，但实际证据仅为人物说法，且明确标注不可视为客观事实，与'强推断'矛盾。"
    }
  ]
}
